def transform(grid):
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 7]
    cycle = [2, 8, 5]

    def assignment(axis):
        coords = sorted({p[axis] for p in pts})
        colors = {}
        for i, x in enumerate(coords):
            group = [p for p in pts if p[axis] == x]
            value = cycle[i % 3]
            if any(p in colors and colors[p] != value for p in group):
                return None
            for p in group:
                colors[p] = value
        return colors

    result = assignment(1)
    if result is None:
        result = assignment(0)
    return [[result.get((r, c), 7) for c in range(len(grid[0]))]
            for r in range(len(grid))]
